<script setup>
import { Link, useForm } from "@inertiajs/vue3";
import { computed, ref } from "vue";
import EnglishBooksLayout from "@/Layouts/EnglishBooksLayout.vue";
const props = defineProps({ book: { type: Object, default: null } });
const editing = computed(() => !!props.book?.id);
const form = useForm({ title: props.book?.title || '', author: props.book?.author || '', cover_url: props.book?.cover_url || '', cover_image: null, difficulty: props.book?.difficulty || null, word_count: props.book?.word_count || null, page_count: props.book?.page_count || null });
const preview = ref(props.book?.cover_image_url || '');
const selectCover = (event) => { const [file] = event.target.files; form.cover_image = file || null; if (file) preview.value = URL.createObjectURL(file); };
const save = () => form.post(editing.value ? route('admin.englishBooks.catalog.update', props.book.id) : route('admin.englishBooks.catalog.store'), { forceFormData: true });
</script>

<template><EnglishBooksLayout :title="editing ? '本の情報を編集' : '本をカタログへ登録'"><div class="mx-auto max-w-3xl px-4 py-8 pb-16 sm:px-8 sm:py-14 sm:pb-20"><Link :href="route('admin.englishBooks.catalog')" class="text-sm font-bold text-[#74665e] hover:text-[#c96b48]">← 本を探すに戻る</Link><section class="mt-8 rounded-2xl border border-[#ded7ca] bg-[#fbf9f4] p-5 shadow-[0_8px_30px_rgba(72,55,40,0.06)] sm:p-8"><p class="text-xs font-bold tracking-[0.18em] text-[#c96b48]">洋書カタログ</p><h1 class="mt-2 font-serif text-3xl font-bold text-[#25323a]">{{ editing ? '本の情報を編集' : '本をカタログへ登録' }}</h1><p class="mt-2 text-sm text-[#74665e]">ここでは全ユーザーで共通となる本の情報だけを登録します。</p><form class="mt-8 grid gap-5 sm:grid-cols-2" @submit.prevent="save"><label class="sm:col-span-2"><span class="text-sm font-bold text-[#3d4b52]">タイトル *</span><input v-model="form.title" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" placeholder="The Great Gatsby" /><p v-if="form.errors.title" class="mt-1 text-xs text-rose-600">{{ form.errors.title }}</p></label><label><span class="text-sm font-bold text-[#3d4b52]">著者</span><input v-model="form.author" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" /></label><div><span class="text-sm font-bold text-[#3d4b52]">表紙画像</span><div class="mt-1.5 flex items-center gap-3"><div class="flex h-20 w-14 shrink-0 items-center justify-center overflow-hidden rounded bg-[#eee7db] text-[10px] font-bold text-[#8b7568]"><img v-if="preview" :src="preview" class="h-full w-full object-cover" /><span v-else>BOOK</span></div><label class="cursor-pointer rounded-lg border border-dashed border-[#c96b48] bg-[#f9ede7] px-3 py-2 text-sm font-bold text-[#a94d2e]">画像を選択<input type="file" accept="image/jpeg,image/png,image/webp" class="sr-only" @change="selectCover" /></label></div></div><label class="sm:col-span-2"><span class="text-sm font-bold text-[#3d4b52]">表紙画像URL（任意）</span><input v-model="form.cover_url" type="url" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" placeholder="https://..." /></label><label><span class="text-sm font-bold text-[#3d4b52]">難易度（1〜5）</span><select v-model="form.difficulty" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm"><option :value="null">未設定</option><option v-for="n in 5" :key="n" :value="n">{{ n }}</option></select></label><label><span class="text-sm font-bold text-[#3d4b52]">語数</span><input v-model.number="form.word_count" type="number" min="0" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" /></label><label><span class="text-sm font-bold text-[#3d4b52]">ページ数</span><input v-model.number="form.page_count" type="number" min="1" class="mt-1.5 block w-full rounded-lg border-[#d6cec1] bg-white text-sm" /></label><div class="sm:col-span-2"><button type="submit" :disabled="form.processing" class="w-full rounded-full bg-[#c96b48] px-7 py-3 text-sm font-bold text-white hover:bg-[#ad5637] disabled:opacity-50 sm:w-auto">{{ editing ? '本の情報を更新' : 'カタログに登録' }}</button></div></form></section></div></EnglishBooksLayout></template>
